<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientPolicyUriAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientPolicyUriAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientPolicyUriAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getPolicyUri returns null on a freshly created holder.
     */
    public function testPolicyUriNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientPolicyUriAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isPolicyUriAssigned());
        $this->assertNull($holder->getPolicyUri());
    }
}
class ImplWithTrustedClientPolicyUriAttributeHolderUnitTest
{
    use TrustedClientPolicyUriAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedPolicyUriRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultPolicyUri();
    }
}
